export function Overlay({
  text = "{{text}}",
  color = "{{color}}",
  opacity = {{opacity}},
  position = "{{position}}",
  dimmed = {{dimmed}},
}) {
  const posStyle = {
    top: { top: 22 },
    center: { top: "50%", transform: "translateY(-50%)" },
    bottom: { bottom: 22 },
  }[position] ?? {};
  return (
    <div style={{ position: "relative", minHeight: 260, overflow: "hidden", borderRadius: 12,
      background: "#FAF7F2", border: "1.5px solid #24143020", boxSizing: "border-box" }}>
      <div style={{ position: "absolute", inset: 0, padding: 22, display: "flex", flexDirection: "column", gap: 10 }}>
        <div style={{ height: 14, borderRadius: 6, background: "#24143014" }} />
        <div style={{ height: 14, width: "80%", borderRadius: 6, background: "#24143014" }} />
        <div style={{ height: 14, width: "58%", borderRadius: 6, background: "#24143014" }} />
      </div>
      {dimmed && <div style={{ position: "absolute", inset: 0, background: "#241430", opacity }} />}
      <div style={{ position: "absolute", left: 22, right: 22, borderRadius: 10, padding: "16px 18px",
        boxShadow: "0 12px 28px rgba(36,20,48,.22)", boxSizing: "border-box", background: color, ...posStyle }}>
        <p style={{ margin: 0, fontSize: 15, fontWeight: 500, color: "#241430" }}>{text}</p>
      </div>
    </div>
  );
}
